    import torch
    if clock.ndim != 2 or clock.shape[1] != len(PREDICTION_TIMES):
        raise ValueError("预测时钟必须为 [batch, 8] one-hot")
    if not torch.all(((clock == 0) | (clock == 1))) or not torch.all(clock.sum(dim=1) == 1):
