"""支持完整精度参数分片的Notebook入口；导入时不读取行情或创建附件。"""

_RUNTIME = None


def _bundle_directory():
    from pathlib import Path
    return Path(__file__).resolve().parent if "__file__" in globals() else Path.cwd()


def _read_bundle():
    import json
    from pathlib import Path
    raw = (_bundle_directory() / "v2801-model.json").read_bytes()
    bundle = json.loads(raw.decode("utf-8-sig"))
    shards = bundle.get('state_dict_shards', [])
    if not isinstance(shards, list):
        raise ValueError('参数分片清单必须是文件名列表')
    if shards:
        state = dict(bundle.get('state_dict', {}))
        for name in shards:
            if not isinstance(name, str) or Path(name).name != name or '/' in name or chr(92) in name or not name.endswith('.json'):
                raise ValueError('参数分片必须是同目录JSON文件')
            part = json.loads((_bundle_directory() / name).read_text(encoding='utf-8-sig'))['state_dict']
            if state.keys() & part.keys():
                raise ValueError('参数分片包含重复张量')
            state.update(part)
        bundle['state_dict'] = state
    return bundle


def _load_modules(bundle, paths):
    import torch
    import builtins
    from pathlib import Path
    from types import ModuleType
    modules = {}

    def local_import(name, globals=None, locals=None, fromlist=(), level=0):
        if level == 0 and name in modules:
            return modules[name]
        return builtins.__import__(name, globals, locals, fromlist, level)

    for relative in paths:
        entry = bundle["sources"][relative]
        name = Path(relative).stem
        module = ModuleType(name)
        module.__file__ = str(_bundle_directory() / Path(relative).name)
        module.__dict__["__builtins__"] = dict(vars(builtins), __import__=local_import)
        modules[name] = module
        exec(compile(entry["text"], module.__file__, "exec"), module.__dict__)
    return modules


def _runtime():
    global _RUNTIME
    if _RUNTIME is None:
        bundle = _read_bundle()
        modules = _load_modules(bundle, bundle["runtime_sources"])
        _RUNTIME = bundle, modules
    return _RUNTIME


def main(datasources, start_date, end_date):
    bundle, modules = _runtime()
    return modules["v2801_predict"].predict(
        datasources, start_date, end_date, model_dir=_bundle_directory(), bundle=bundle,
    )


def reproduce(workspace, data_root, *, training_confirmed=False):
    """显式调用才启动预处理和训练；workspace 必须是不存在的新目录。"""
    if not training_confirmed:
        raise ValueError("v2801 训练复现尚待用户明确确认")
    bundle = _read_bundle()
    modules = _load_modules(bundle, ["solutions/v2801/v2801_reproduce.py"])
    return modules["v2801_reproduce"].reproduce(bundle, workspace, data_root,
                                           training_confirmed=True)

